  noir: {
    id: 'noir',
    label: 'Noir Print',
    stops: ['#e8e8e8', '#5a5a6a', '#0b0b12'],
    blend: 'overlay',
    strength: 0.55,
    caption: '#f5efe4',
    captionStroke: '#000000',
  },
